"""v18 copy that only jams preflop when FACING a raise (3-bet/4-bet jam) with top ~10% (EQ3 >= 0.60); isolates v18's width = max(pf_open, pf_3bet) range-reading leak"""
"""Discard Hold'em bot.

Strategy: range-weighted Monte Carlo equity + online opponent modelling.
  * Vectorised numpy hand evaluator (any 5-7 cards).
  * Opponent hands are sampled, then weighted by how consistent they are with the
    opponent's actions (preflop table percentile, postflop strength percentile,
    and the exposed discard), using thresholds learned from the opponent's own
    frequencies during this leg.
  * Decisions compare range equity with pot odds; bluff / value sizing adapts to
    how often the opponent folds.
All debug output goes to stderr.
"""
import sys
import json
import time
import math
import random
from itertools import combinations, permutations

import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
CARD_ID = {r + s: i * 4 + j for i, r in enumerate(RANKS) for j, s in enumerate(SUITS)}
ID_CARD = {v: k for k, v in CARD_ID.items()}

RNG = np.random.default_rng()

# Strategy parameters. PB_PARAMS (JSON) overrides them for local A/B testing only;
# it is never set in the tournament.
P = {
    "open_t": 0.35, "limp_t": 0.30, "open_size": 0.75, "bb_raise_t": 0.60,
    "pf_reraise_t": 0.62, "pf_call_margin": 0.04,
    "raise_t": 0.68, "call_margin": 0.22, "bluff_raise": 0.3,
    "bet_t": 0.58, "bet_base": 0.45, "bet_slope": 0.5, "bluff_scale": 30,
    "disc_w": 0.35, "agg_floor": 0.08, "mdf": 0.0, "size_aware": 1, "balanced": 0, "bal_frac": 0.7, "bluff_size": 0.33, "trap_p": 1.0, "river_gto": 1, "steal_k": 0.1, "disc_learn": 0, "prior_k": 1.0, "time_frac": 0.06, "station_cap": 1.6, "cm_ip": 0.0, "cm_oop": 0.12, "cm_size": 0.3, "mini_n": 300,
}
try:
    import os
    P.update(json.loads(os.environ.get("PB_PARAMS", "{}")))
except Exception:
    pass

# ------------------------------------------------------------------ lookup tables

M = 1 << 13
POP = np.array([bin(m).count("1") for m in range(M)], dtype=np.int64)


def _topk_table(k):
    """For every 13-bit mask, the mask of its k highest set bits (vectorised)."""
    m = np.arange(M, dtype=np.int64)
    out = np.zeros(M, dtype=np.int64)
    taken = np.zeros(M, dtype=np.int64)
    for r in range(12, -1, -1):
        bit = (m >> r) & 1
        use = (bit == 1) & (taken < k)
        out |= np.where(use, 1 << r, 0)
        taken += use
    return out


def _straight_table():
    m = np.arange(M, dtype=np.int64)
    out = np.zeros(M, dtype=np.int64)
    wheel = 0b1000000001111
    out = np.where(m & wheel == wheel, 4, out)
    for hi in range(4, 13):  # ascending so the highest straight wins
        w = 0b11111 << (hi - 4)
        out = np.where(m & w == w, hi + 1, out)
    return out


TOP1, TOP2, TOP3, TOP5 = (_topk_table(k) for k in (1, 2, 3, 5))
STRAIGHT = _straight_table()
# number of distinct ranks that would complete a straight (2 = open-ended, 1 = gutshot)
_m = np.arange(M, dtype=np.int64)
DRAW = np.minimum(2, sum(((_m >> x) & 1 == 0) & (STRAIGHT[_m | (1 << x)] > 0) for x in range(13)))
DRAW = np.where(STRAIGHT > 0, 0, DRAW).astype(np.int64)
W13 = (1 << np.arange(13)).astype(np.int64)
SUBMASK = (1 << 26) - 1


def evaluate(cards):
    """cards: int array (N, k), k in 5..7 -> int64 scores (higher is better)."""
    N, k = cards.shape
    R = cards >> 2
    S = cards & 3
    bits = np.left_shift(1, R).astype(np.int64)
    rows = np.arange(N)
    cnt = np.zeros((N, 13), dtype=np.int8)
    for j in range(k):
        cnt[rows, R[:, j]] += 1
    rmask = np.bitwise_or.reduce(bits, axis=1)
    fmask = np.zeros(N, dtype=np.int64)
    for s in range(4):
        sm = np.bitwise_or.reduce(np.where(S == s, bits, 0), axis=1)
        fmask = np.where(POP[sm] >= 5, sm, fmask)
    ge2 = (cnt >= 2) @ W13
    ge3 = (cnt >= 3) @ W13
    ge4 = (cnt >= 4) @ W13
    t3 = TOP1[ge3]
    fh_pair = TOP1[ge2 & ~t3]
    sf = STRAIGHT[fmask]
    st = STRAIGHT[rmask]
    conds = [sf > 0, ge4 > 0, (ge3 > 0) & (fh_pair > 0), fmask > 0, st > 0,
             ge3 > 0, POP[ge2] >= 2, ge2 > 0]
    p2 = TOP2[ge2]
    vals = [
        (8 << 26) | sf,
        (7 << 26) | (ge4 << 13) | TOP1[rmask & ~ge4],
        (6 << 26) | (t3 << 13) | fh_pair,
        (5 << 26) | TOP5[fmask],
        (4 << 26) | st,
        (3 << 26) | (t3 << 13) | TOP2[rmask & ~t3],
        (2 << 26) | (p2 << 13) | TOP1[rmask & ~p2],
        (1 << 26) | (ge2 << 13) | TOP3[rmask & ~ge2],
    ]
    return np.select(conds, vals, default=TOP5[rmask])


def strength(cards, draws=True):
    """Float strength metric: category + kicker fraction + draw bonus."""
    sc = evaluate(cards)
    cat = sc >> 26
    v = cat + (sc & SUBMASK) / float(1 << 26)
    if draws:
        S = cards & 3
        maxsuit = np.max(np.stack([(S == s).sum(1) for s in range(4)], 1), 1)
        rmask = np.bitwise_or.reduce(np.left_shift(1, cards >> 2).astype(np.int64), axis=1)
        bonus = 0.9 * (maxsuit == 4) + 0.35 * DRAW[rmask]
        v = v + np.where(cat < 4, bonus, 0.0)
    return v


# keep option i discards card i
KEEPS = ((1, 2), (0, 2), (0, 1))


def keep_values(h3, flop):
    """h3 (N,3), flop (N,3) -> (N,3) heuristic value of keeping each pair."""
    return np.stack([strength(np.concatenate([h3[:, kp], flop], 1)) for kp in KEEPS], 1)


def heuristic_keep(h3, flop):
    """Kept 2 cards (N,2) under the flop heuristic."""
    idx = np.argmax(keep_values(h3, flop), 1)
    kp = np.array(KEEPS)[idx]  # (N,2)
    return np.take_along_axis(h3, kp, 1), idx


def sample_cards(deck, n_rows, m):
    """n_rows samples of m distinct cards from deck (1-D array)."""
    r = RNG.random((n_rows, len(deck)))
    idx = np.argpartition(r, m, axis=1)[:, :m] if m < len(deck) else np.argsort(r, 1)
    return deck[idx]


# ----------------------------------------------- preflop table (3-card hands)

# Equity of every 3-card hand (combinations order) vs a random 3-card hand, both
# discarding by the flop heuristic. uint16 little-endian, base64. Built by tools/precompute.py.
EQ3_B64 = ""  # @@PRE3@@


def build_pct3():
    """52^3 lookups (any card order) of preflop equity and percentile."""
    import base64
    combos = np.array(list(combinations(range(52), 3)), dtype=np.int64)
    eq = np.frombuffer(base64.b64decode(EQ3_B64), dtype="<u2").astype(np.float32) / 65535
    pct = np.empty(len(eq), dtype=np.float32)
    pct[np.argsort(eq, kind="stable")] = np.arange(len(eq)) / (len(eq) - 1)
    table = np.zeros((52, 52, 52), dtype=np.float32)
    eqt = np.zeros((52, 52, 52), dtype=np.float32)
    a, b, c = combos[:, 0], combos[:, 1], combos[:, 2]
    for x, y, z in permutations((a, b, c)):
        table[x, y, z] = pct
        eqt[x, y, z] = eq
    return table, eqt


PCT3, EQ3 = build_pct3()


# ----------------------------------------------------------- opponent model

def replay(history):
    """Walk a hand's history tracking bets. Yields (street, actor, action, r, facing)
    where r = raise size / pot after calling (bet-to-pot ratio) for raises, else 0."""
    out = []
    street, pot, bets = None, 0, None
    for h in history:
        if h["street"] != street:
            if street is None:  # preflop: the button acts first and posted 1
                btn = h["actor"]
                bets = {btn: 1, ("opp" if btn == "me" else "me"): 2}
            else:
                pot += bets["me"] + bets["opp"]
                bets = {"me": 0, "opp": 0}
            street = h["street"]
        a, act = h["actor"], h["action"]
        o = "opp" if a == "me" else "me"
        facing = bets[o] > bets[a]
        r = 0.0
        if act == "raise":
            amt = h.get("amount") or 0
            after_call = pot + 2 * bets[o]
            r = (amt - bets[o]) / max(1, after_call)
            bets[a] = amt
        elif act == "call":
            bets[a] = bets[o]
        out.append((street, a, act, r, facing))
    return out



class OppModel:
    def __init__(self):
        self.c = {k: 0 for k in (
            "pf_open_n", "pf_open", "pf_limp",
            "pf_face_n", "pf_face_fold", "pf_face_raise",
            "po_open_n", "po_open",
            "po_face_n", "po_face_fold", "po_face_raise",
            "sd_n", "agg_sd_n", "agg_sd_weak", "po_open_mid", "po_open_big", "disc_n", "disc_heur", "disc_low", "hands")}

    def f(self, a, n, prior, w):
        w = w * P["prior_k"]
        return (self.c[a] + prior * w) / (self.c[n] + w)

    # frequencies (Bayesian with priors)
    @property
    def pf_open(self):
        return self.f("pf_open", "pf_open_n", 0.5, 6)

    @property
    def pf_fold(self):
        return self.f("pf_face_fold", "pf_face_n", 0.3, 5)

    @property
    def pf_3bet(self):
        return self.f("pf_face_raise", "pf_face_n", 0.15, 6)

    @property
    def po_agg(self):
        return self.f("po_open", "po_open_n", 0.35, 6)

    @property
    def po_fold(self):
        return self.f("po_face_fold", "po_face_n", 0.4, 5)

    @property
    def po_raise(self):
        return self.f("po_face_raise", "po_face_n", 0.12, 8)

    def open_width(self, r):
        """Share of opportunities where they open-bet at least this big (postflop)."""
        if r > 1.2:
            # Big bets only mean "strong" if they're rare. Someone overbetting a lot
            # (maniac, polarized bluffer) sizes independently of strength, so blend
            # back to their overall betting frequency as overbets get common.
            raw = self.f("po_open_big", "po_open_n", 0.05, 6)
            t = min(1.0, max(0.0, (raw - 0.06) / 0.12))
            return raw + (max(raw, self.po_agg) - raw) * t
        if r > 0.6:
            return (self.c["po_open_mid"] + self.c["po_open_big"] + 0.15 * 6) / (self.c["po_open_n"] + 6)
        return self.po_agg

    @property
    def bluff_rate(self):
        """Share of opponent postflop aggression that turned out weak at showdown."""
        return self.f("agg_sd_weak", "agg_sd_n", 0.25, 4)

    @property
    def disc_style(self):
        """(share of showdowns matching our keep heuristic, share discarding the lowest card)"""
        n = self.c["disc_n"]
        return ((self.c["disc_heur"] + 0.6 * 4) / (n + 4), (self.c["disc_low"] + 0.2 * 4) / (n + 4))

    def learn_discard(self, msg):
        opp, od = msg.get("opp_hole_cards"), msg.get("opp_discard")
        board = msg.get("board") or []
        if msg.get("result") != "showdown" or not opp or not od or len(board) < 3:
            return
        v3 = np.array([[CARD_ID[opp[0]], CARD_ID[opp[1]], CARD_ID[od]]])
        kv = keep_values(v3, np.array([[CARD_ID[c] for c in board[:3]]]))
        self.c["disc_n"] += 1
        self.c["disc_heur"] += int(np.argmax(kv[0]) == 2)
        self.c["disc_low"] += int(v3[0, 2] < v3[0, :2].min())

    def learn_showdown(self, msg):
        opp = msg.get("opp_hole_cards")
        board = msg.get("board") or []
        if msg.get("result") != "showdown" or not opp or len(board) != 5:
            return
        if not any(h["actor"] == "opp" and h["action"] == "raise" and h["street"] != "preflop"
                   for h in msg.get("history", [])):
            return
        o = np.array([CARD_ID[c] for c in opp]); b = np.array([CARD_ID[c] for c in board])
        known = [CARD_ID[c] for c in (msg.get("my_hole_cards") or []) + [msg.get("opp_discard")] if c]
        deck = np.setdiff1d(np.arange(52), np.concatenate([o, b, np.array(known, dtype=int)]))
        n = 400
        r = sample_cards(deck, n, 2)
        bt = np.tile(b, (n, 1))
        os_ = evaluate(np.concatenate([np.tile(o, (n, 1)), bt], 1))
        rs = evaluate(np.concatenate([r, bt], 1))
        eq = float(((os_ > rs) + 0.5 * (os_ == rs)).mean())
        self.c["agg_sd_n"] += 1
        if eq < 0.5:
            self.c["agg_sd_weak"] += 1

    def update(self, history):
        for street, actor, act, r, facing in replay(history):
            if actor == "opp" and street != "preflop" and act == "raise" and not facing:
                if r > 1.2:
                    self.c["po_open_big"] += 1
                elif r > 0.6:
                    self.c["po_open_mid"] += 1
        self.c["hands"] += 1
        street = None
        facing = {"me": False, "opp": False}
        for h in history:
            if h["street"] != street:
                street = h["street"]
                facing = {"me": False, "opp": False}
                pf_raised_by_me = False
                pf_first = True
            actor, act = h["actor"], h["action"]
            if street == "preflop":
                if actor == "opp":
                    if pf_raised_by_me:
                        self.c["pf_face_n"] += 1
                        if act == "fold":
                            self.c["pf_face_fold"] += 1
                        elif act == "raise":
                            self.c["pf_face_raise"] += 1
                    elif pf_first:  # opp on button, first in
                        self.c["pf_open_n"] += 1
                        if act == "raise":
                            self.c["pf_open"] += 1
                        elif act == "call":
                            self.c["pf_limp"] += 1
                if act == "raise":
                    pf_raised_by_me = actor == "me"
                pf_first = False
            else:
                if actor == "opp":
                    if facing["opp"]:
                        self.c["po_face_n"] += 1
                        if act == "fold":
                            self.c["po_face_fold"] += 1
                        elif act == "raise":
                            self.c["po_face_raise"] += 1
                    else:
                        self.c["po_open_n"] += 1
                        if act == "raise":
                            self.c["po_open"] += 1
                if act == "raise":
                    other = "opp" if actor == "me" else "me"
                    facing[other] = True
                    facing[actor] = False
                elif act == "call":
                    facing = {"me": False, "opp": False}


def soft(p, t, width=0.07, floor=0.04):
    return floor + (1 - floor) / (1 + np.exp(-(p - t) / width))


def pct_rank(x):
    n = len(x)
    r = np.empty(n)
    r[np.argsort(x, kind="stable")] = np.arange(n)
    return r / max(1, n - 1)


# ------------------------------------------------------------------ the bot

# River betting from a solved toy game: CFR+ on a one-street game where both players hold a
# uniform strength bucket (20 buckets), pot 1, bets 1/3 or 3/4 pot, pot-size raises, then
# fold/call (scratch solver, exploitability < 1e-4 pot). Only the two betting spots are used:
# OOP first to act (bet 1/3, bet 3/4, check) and IP checked to (check, bet 1/3, bet 3/4).
# Rows = our equity vs their pre-river range. Facing bets stays exploitative (it adapts).
RIVER_ROOT = [(0.48, 0.21, 0.32), (0.52, 0.18, 0.31), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (0.00, 0.09, 0.91), (0.00, 0.26, 0.74), (0.00, 0.33, 0.67), (1.00, 0.00, 0.00), (0.00, 0.22, 0.78)]
RIVER_X = [(0.00, 0.33, 0.67), (0.00, 0.33, 0.67), (0.32, 0.28, 0.40), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (1.00, 0.00, 0.00), (0.05, 0.95, 0.00), (0.03, 0.97, 0.00), (0.04, 0.96, 0.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.00, 1.00), (0.00, 0.96, 0.04), (0.00, 0.00, 1.00)]


class Bot:
    def __init__(self):
        self.opp = OppModel()
        self.total_hands = 200
        self.hand_id = 0
        self.time_bank = 30000
        self.target_ms = 20.0
        self.panic = False
        self.emergency = False
        self.lean = False
        self.mult = 1.0
        self.cost_ema = None
        self.bud_hand = None
        self.bud_left = None
        self.ms_per_k = 8.0  # pessimistic start; refined online
        self.samples = 0
        self.hole = []
        self.seat = None
        self.my_discard = None
        self.opp_discard = None
        self.faced = {"flop": [], "turn": [], "river": []}  # our equities when facing bets

    # --------------------------------------------------- range weights
    def opp_street_actions(self, history):
        """street -> counts of the opponent's actions, plus the size (bet/pot) and kind
        of their biggest raise on that street."""
        out = {}
        for street, actor, act, r, facing in replay(history):
            if actor != "opp":
                continue
            d = out.setdefault(street, {"raise": 0, "call": 0, "check": 0, "r": 0.0, "open": False})
            if act in d:
                d[act] += 1
            if act == "raise" and r >= d["r"]:
                d["r"], d["open"] = r, not facing
        return out

    def weight_by_action(self, w, pct, acts, street):
        if not acts:
            return w
        o = self.opp
        if street == "preflop":
            open_f, face_raise = o.pf_open, o.pf_3bet
            fold_f = o.pf_fold
        else:
            open_f, face_raise = o.po_agg, o.po_raise
            fold_f = o.po_fold
        nr = acts["raise"]
        floor = 0.04
        if street != "preflop":  # learned: how often their aggression is a bluff
            floor = float(np.clip(P["agg_floor"] * o.bluff_rate / 0.25, 0.02, 0.6))
        if nr >= 2:
            w = w * soft(pct, 1 - min(open_f, face_raise) * 0.6, 0.07, floor)
        elif nr == 1:
            width = max(open_f, face_raise)
            if P["size_aware"] and street != "preflop":
                if acts["open"]:
                    width = o.open_width(acts["r"])
                elif acts["r"] > 1.2:
                    width = face_raise * 0.6
            w = w * soft(pct, 1 - width, 0.08, floor)
        elif acts["call"]:
            w = w * soft(pct, fold_f * 0.8, 0.1, 0.1)
            w = w * (1 - 0.35 * soft(pct, 1 - face_raise, 0.05, 0.0))
        elif acts["check"]:
            w = w * (1 - 0.5 * soft(pct, 1 - open_f, 0.06, 0.0))
        return w

    # --------------------------------------------------- equity engines
    def n_samples(self, base):
        # base is the relative weight of this decision; ms_per_k is measured online
        if self.panic:  # short on time: a small Monte Carlo still beats the no-MC heuristic by a lot
            return P["mini_n"]
        n = self.target_ms / self.ms_per_k * 1000 * base / 2000
        return int(max(150 if self.lean else 300, min(12000, n)))

    def equity_preflop(self, hole, history):
        h = np.array([CARD_ID[c] for c in hole])
        deck = np.setdiff1d(np.arange(52), h)
        N = self.n_samples(1500)
        self.samples += N
        s = sample_cards(deck, N, 8)
        v3, board = s[:, :3], s[:, 3:]
        acts = self.opp_street_actions(history)
        w = np.ones(N)
        w = self.weight_by_action(w, PCT3[v3[:, 0], v3[:, 1], v3[:, 2]], acts.get("preflop"), "preflop")
        h3 = np.tile(h, (N, 1))
        hk, _ = heuristic_keep(h3, board[:, :3])
        vk, _ = heuristic_keep(v3, board[:, :3])
        hs = evaluate(np.concatenate([hk, board], 1))
        vs = evaluate(np.concatenate([vk, board], 1))
        win = (hs > vs) + 0.5 * (hs == vs)
        return float((w * win).sum() / w.sum())

    def equity_flop3(self, hole, board, history):
        """Hero holds 3 cards on the flop. Returns per-keep equities (3,)."""
        h = np.array([CARD_ID[c] for c in hole])
        b = np.array([CARD_ID[c] for c in board[:3]])
        deck = np.setdiff1d(np.arange(52), np.concatenate([h, b]))
        N = self.n_samples(2000)
        self.samples += N * 2
        s = sample_cards(deck, N, 5)
        v3, run = s[:, :3], s[:, 3:]
        flop = np.tile(b, (N, 1))
        acts = self.opp_street_actions(history)
        w = np.ones(N)
        w = self.weight_by_action(w, PCT3[v3[:, 0], v3[:, 1], v3[:, 2]], acts.get("preflop"), "preflop")
        kv = keep_values(v3, flop)
        if acts.get("flop"):
            w = self.weight_by_action(w, pct_rank(kv.max(1)), acts["flop"], "flop")
        vk = np.take_along_axis(v3, np.array(KEEPS)[np.argmax(kv, 1)], 1)
        full = np.concatenate([flop, run], 1)
        vs = evaluate(np.concatenate([vk, full], 1))
        eqs = []
        for kp in KEEPS:
            hk = np.tile(h[list(kp)], (N, 1))
            hs = evaluate(np.concatenate([hk, full], 1))
            win = (hs > vs) + 0.5 * (hs == vs)
            eqs.append(float((w * win).sum() / w.sum()))
        return eqs

    def equity_post(self, hole, board, history, skip_river=False):
        """Hero holds 2 cards after the discard (turn / river, or all-in flop)."""
        h = np.array([CARD_ID[c] for c in hole])
        b = np.array([CARD_ID[c] for c in board])
        dead = [CARD_ID[c] for c in (self.my_discard, self.opp_discard) if c]
        od = CARD_ID[self.opp_discard] if self.opp_discard else None
        deck = np.setdiff1d(np.arange(52), np.concatenate([h, b, np.array(dead, dtype=int)]))
        N = self.n_samples(2500)
        self.samples += N
        need = 5 - len(b)
        s = sample_cards(deck, N, 2 + need)
        v2 = s[:, :2]
        full = np.concatenate([np.tile(b, (N, 1)), s[:, 2:]], 1)
        acts = self.opp_street_actions(history)
        w = np.ones(N)
        flop = full[:, :3]
        if od is not None:
            v3 = np.concatenate([v2, np.full((N, 1), od)], 1)
            w = self.weight_by_action(w, PCT3[v3[:, 0], v3[:, 1], v3[:, 2]], acts.get("preflop"), "preflop")
            kv = keep_values(v3, flop)
            # discard consistency: would our heuristic have discarded od (index 2)?
            if P["disc_learn"]:
                # mixture of discard styles learned from showdowns: our best-keep
                # heuristic vs "throw the lowest card" (the starter bot's rule, which
                # is simply the minimum card id). The rest is treated as noise.
                ph, pl = self.opp.disc_style
                heur = np.argmax(kv, 1) == 2
                low = od < v2.min(1)
                w = w * (0.25 + ph * heur + pl * low)
            else:
                w = w * np.where(np.argmax(kv, 1) == 2, 1.0, P["disc_w"])
            if acts.get("flop"):
                w = self.weight_by_action(w, pct_rank(kv.max(1)), acts["flop"], "flop")
        if acts.get("turn") and len(b) >= 4:
            st = strength(np.concatenate([v2, full[:, :4]], 1))
            w = self.weight_by_action(w, pct_rank(st), acts["turn"], "turn")
        if acts.get("river") and len(b) == 5 and not skip_river:
            st = strength(np.concatenate([v2, full], 1), draws=False)
            w = self.weight_by_action(w, pct_rank(st), acts["river"], "river")
        hs = evaluate(np.concatenate([np.tile(h, (N, 1)), full], 1))
        vs = evaluate(np.concatenate([v2, full], 1))
        win = (hs > vs) + 0.5 * (hs == vs)
        return float((w * win).sum() / w.sum())

    # --------------------------------------------------- decisions
    @staticmethod
    def act(a, amount=None):
        m = {"type": "action", "action": a}
        if amount is not None:
            m["amount"] = int(amount)
        return m

    def raise_to(self, req, frac):
        target = req["opp_bet"] + frac * (req["pot"] + req["to_call"])
        target = int(round(max(req["min_raise"], min(req["max_raise"], target))))
        # only round up to all-in when the raise is already most of the stack: jamming at 60% put
        # whole stacks in with hands that wanted a big-but-not-all-in raise (+164 / +198 vs v16)
        if target >= 0.85 * req["max_raise"] + 0.15 * req["my_bet"]:
            target = req["max_raise"]
        return target

    def choose_action(self, req):
        legal = req["legal_actions"]
        street = req["street"]
        hist = req.get("history", [])
        hole = self.hole
        if self.emergency:
            E = self.quick_equity(hole, req["board"])
        elif street == "preflop":
            E = self.timed(self.equity_preflop, hole, hist)
        elif len(hole) == 3:
            E = max(self.timed(self.equity_flop3, hole, req["board"], hist))
        else:
            E = self.timed(self.equity_post, hole, req["board"], hist)

        pot, to_call = req["pot"], req["to_call"]
        can_raise = "raise" in legal
        o = self.opp
        fold_f = o.pf_fold if street == "preflop" else o.po_fold
        station = fold_f < 0.25
        rr = random.random()
        log(f"h{self.hand_id} {street} E={E:.3f} pot={pot} tc={to_call} fold={fold_f:.2f}")

        if street == "preflop":
            return self.preflop(req, E, rr)

        if to_call > 0:
            odds = to_call / (pot + to_call)
            self.faced[street].append(E)
            margin = 0.0 if street == "river" else (
                P["call_margin"] + (P["cm_ip"] if self.seat == "button" else P["cm_oop"]))
            # vs tiny bets (under cm_size of the pot) shrink the margin quadratically: a flat
            # +0.22/0.34 equity margin vs a 1/8 pot bet folds hands with ~40% equity
            margin *= min(1.0, to_call / max(1, pot - to_call) / P["cm_size"]) ** 2
            if can_raise and E > P["raise_t"] + (0.04 if req["raises_left"] < 3 else 0.0):
                return self.act("raise", self.raise_to(req, 0.8 if P["balanced"] and not station
                                                       else (0.9 if E > 0.85 else 0.7)))
            if E >= odds + margin:
                return self.act("call")
            if self.mdf_defend(street, E, odds, o):
                return self.act("call")
            # occasional bluff-raise vs folders, with some equity on early streets
            if can_raise and street != "river" and fold_f > 0.55 and E > 0.25 and rr < P["bluff_raise"]:
                return self.act("raise", self.raise_to(req, 0.8))
            return self.act("fold") if "fold" in legal else self.act("check")

        # not facing a bet
        if not can_raise:
            return self.act("check")
        if street == "river" and P["river_gto"] and not station and not self.emergency:
            r = self.river_bet(req, hist)
            if r:
                return r
        thresh = P["bet_t"] + {"flop": 0.0, "turn": 0.02, "river": 0.04}[street]
        if station:
            thresh -= 0.04
        # trap: vs frequent bettors, check some monsters to induce a bluff, then raise
        if (E > 0.8 and street != "river" and o.po_agg > 0.5 and not station
                and random.random() < P["trap_p"]):
            return self.act("check")
        if E > thresh:
            frac = P["bet_base"] + (E - thresh) * P["bet_slope"]
            cap = 1.1
            if station:
                frac *= 1.3
                if E > 0.9:
                    cap = P["station_cap"]
            elif P["balanced"]:
                frac = self.bal_size(rr)
            return self.act("raise", self.raise_to(req, min(cap, frac)))
        # bluff / semi-bluff
        if street == "river":
            p = max(0.0, min(0.35, fold_f - 0.35)) if E < 0.25 else 0.0
        else:
            p = max(0.0, min(0.5, fold_f - 0.2)) * (1.0 if E > 0.3 else 0.5)
        if rr < p * P["bluff_scale"] and not self.emergency:
            size = self.bal_size(rr) if P["balanced"] else P["bluff_size"] + 0.2 * (random.random() - 0.5)
            return self.act("raise", self.raise_to(req, size))
        return self.act("check")

    def river_bet(self, req, hist):
        """First river action (OOP) or checked to (IP): sample from the solved table."""
        seq = [act for st, actor, act, r, _ in replay(hist) if st == "river"]
        oop = self.seat != "button"
        if oop and not seq:
            table, acts = RIVER_ROOT, (0.33, 0.75, 0)
        elif not oop and seq == ["check"]:
            table, acts = RIVER_X, (0, 0.33, 0.75)
        else:
            return None
        E = self.timed(self.equity_post, self.hole, req["board"], hist, True)
        size = random.choices(acts, weights=table[min(19, int(E * 20))])[0]
        log(f"h{self.hand_id} river table E={E:.2f} -> {size}")
        return self.act("raise", self.raise_to(req, size)) if size else self.act("check")

    @staticmethod
    def bal_size(rr):
        """Strength-independent bet size so sizing doesn't leak our hand. Uses a fresh
        random draw so the size isn't correlated with the bluff decision."""
        return P["bal_frac"] + 0.15 * (random.random() - 0.5)

    def mdf_defend(self, street, E, odds, o):
        """Don't over-fold vs frequent bettors: continue with the top (1 - k*alpha)
        of the equities we've held when facing a bet on this street.
        alpha = odds of a bet is exactly the fold share that makes a pure bluff break even."""
        k = P["mdf"]
        hist = self.faced[street]
        if k <= 0 or len(hist) < 15 or o.po_agg < 0.4 or E < 0.6 * odds:
            return False
        fold_cap = min(0.9, k * odds / (1 - odds))  # alpha = bet / (pot + bet)
        rank = sum(1 for e in hist if e < E) / len(hist)
        return rank >= fold_cap

    def preflop(self, req, E, rr):
        legal = req["legal_actions"]
        pot, to_call = req["pot"], req["to_call"]
        can_raise = "raise" in legal
        o = self.opp
        seat = self.seat
        if to_call == 0:  # big blind option after a limp
            if can_raise and E > P["bb_raise_t"]:
                return self.act("raise", self.raise_to(req, 1.0))
            if can_raise and rr < 0.15 and o.pf_fold > 0.5:
                return self.act("raise", self.raise_to(req, 1.0))
            return self.act("check")
        if can_raise and not (seat == "button" and req["my_bet"] == 1):
            hh = [CARD_ID[c] for c in self.hole]
            if EQ3[hh[0], hh[1], hh[2]] >= P.get("rt_jam", 0.60):
                return self.act("raise", req["max_raise"])
        odds = to_call / (pot + to_call)
        if seat == "button" and req["my_bet"] == 1 and to_call == 1:
            # first in: open almost everything. 3-card equities are compressed (worst hand
            # ~31% vs random) so initiative is worth more than hand selection; open_t 0.35
            # opens ~98%, limp/fold only the very bottom (+398 +-103 vs v7, 48 seeds)
            open_t = P["open_t"] - P["steal_k"] * (o.pf_fold - 0.3)
            if can_raise and E > open_t:
                return self.act("raise", self.raise_to(req, P["open_size"]))
            if E > P["limp_t"]:
                return self.act("call")
            return self.act("fold")
        # facing a raise
        reraise_t = P["pf_reraise_t"] + (0.0 if req["raises_left"] >= 2 else 0.06)
        if can_raise and E > reraise_t:
            return self.act("raise", self.raise_to(req, 1.0))
        if E >= odds + P["pf_call_margin"] or (to_call <= 2 and E > 0.35):
            return self.act("call")
        return self.act("fold")

    def quick_equity(self, hole, board):
        """No-Monte-Carlo fallback used only when the time bank runs low."""
        h = [CARD_ID[c] for c in hole]
        if not board:
            return float(EQ3[h[0], h[1], h[2]])
        b = [CARD_ID[c] for c in board]
        if len(h) == 3:
            kv = keep_values(np.array([h]), np.array([b[:3]]))[0]
            v = float(kv.max())
        else:
            v = float(strength(np.array([h + b]), draws=len(b) < 5)[0])
        return float(np.interp(v, [0, 1, 1.5, 2, 3, 4, 5], [0.25, 0.42, 0.55, 0.66, 0.78, 0.86, 0.9]))

    def choose_discard(self, req):
        hole = req["hole_cards"]
        if self.emergency:
            kv = keep_values(np.array([[CARD_ID[c] for c in hole]]),
                             np.array([[CARD_ID[c] for c in req["board"][:3]]]))[0]
            return {"type": "discard", "card": hole[int(np.argmax(kv))]}
        eqs = self.timed(self.equity_flop3, hole, req["board"], self.cur_history)
        i = int(np.argmax(eqs))
        log(f"h{self.hand_id} discard eqs={[round(e, 3) for e in eqs]} -> {hole[i]}")
        return {"type": "discard", "card": hole[i]}

    # --------------------------------------------------- time management
    def budget(self, req):
        """Steer by what the engine actually charges us (time_left_ms), not by our
        own estimates: fixed overhead and pipe latency dominate on a slow box."""
        left = req.get("time_left_ms", self.time_bank)
        hid = self.hand_id
        remaining = max(1, self.total_hands - hid + 1)
        share = left / remaining  # ms we can afford per remaining hand
        if hid != self.bud_hand:
            if self.bud_hand is not None:
                spent = max(0.0, self.bud_left - left) / max(1, hid - self.bud_hand)
                self.cost_ema = spent if self.cost_ema is None else 0.85 * self.cost_ema + 0.15 * spent
                ratio = self.cost_ema / max(1.0, share)
                if ratio > 0.45:
                    self.mult = max(0.03, self.mult * 0.75)
                elif ratio < 0.2:
                    self.mult = min(1.0, self.mult * 1.1)
            self.bud_hand, self.bud_left = hid, left
        self.target_ms = max(0.5, min(150.0, P["time_frac"] * share / 5.0 * self.mult))
        c = self.cost_ema
        self.lean = share < 90 or self.mult < 0.4
        self.panic = (share < 40 or left < 1500 or (c is not None and c > 0.8 * share)
                      or bool(P.get("force_panic")))
        # running slow (cost over budget) or nearly out: no MC at all, like before. Only a plain
        # shortage of ms per hand gets the small MC (300 samples plays at full strength).
        self.emergency = (left < 1500 or share < 15 or (c is not None and c > 0.8 * share)
                          or bool(P.get("force_emergency")))

    def timed(self, fn, *args):
        t0 = time.perf_counter()
        n0 = self.samples
        r = fn(*args)
        dt = (time.perf_counter() - t0) * 1000
        k = max(1, self.samples - n0) / 1000
        self.ms_per_k = 0.8 * self.ms_per_k + 0.2 * (dt / k)
        return r

    # --------------------------------------------------- main loop
    def run(self):
        self.cur_history = []
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue
            try:
                msg = json.loads(line)
            except ValueError:
                continue
            if not isinstance(msg, dict):  # valid JSON but not a message (e.g. [] or 42)
                continue
            t = msg.get("type")
            reply = None
            try:
                if t == "action_request":
                    self.cur_history = msg.get("history", [])
                    self.budget(msg)
                    reply = self.safe_action(msg)
                elif t == "discard_request":
                    self.budget(msg)
                    reply = self.safe_discard(msg)
                elif t == "new_hand":
                    self.hand_id = msg.get("hand_id", self.hand_id + 1)
                    self.seat = msg.get("seat")
                    self.hole = list(msg.get("hole_cards", []))
                    self.my_discard = self.opp_discard = None
                    self.cur_history = []
                elif t == "discard_result":
                    self.my_discard = msg.get("my_discard")
                    self.opp_discard = msg.get("opp_discard")
                    self.hole = list(msg.get("hole_cards", self.hole))
                elif t == "hand_result":
                    self.opp.update(msg.get("history", []))
                    self.opp.learn_showdown(msg)
                    self.opp.learn_discard(msg)
                elif t == "init":
                    self.total_hands = msg.get("total_hands", 200)
                    self.time_bank = msg.get("time_bank_ms", 30000)
                elif t == "match_end":
                    break
            except Exception as e:  # never crash on bookkeeping
                log(f"error on {t}: {e!r}")
            if reply is not None:
                print(json.dumps(reply), flush=True)

    def safe_action(self, req):
        try:
            r = self.choose_action(req)
            legal = req["legal_actions"]
            if r["action"] not in legal:
                raise ValueError(f"illegal {r}")
            if r["action"] == "raise":
                r["amount"] = int(max(req["min_raise"], min(req["max_raise"], r["amount"])))
            return r
        except Exception as e:
            log(f"action error: {e!r}")
            legal = req.get("legal_actions", [])
            return self.act("check") if "check" in legal else self.act("fold")

    def safe_discard(self, req):
        try:
            return self.choose_discard(req)
        except Exception as e:
            log(f"discard error: {e!r}")
            hole = req["hole_cards"]
            return {"type": "discard", "card": min(hole, key=lambda c: RANKS.index(c[0]))}


_LOG_BYTES = 0


def log(s):
    global _LOG_BYTES
    if _LOG_BYTES < 60000:
        _LOG_BYTES += len(s) + 1
        print(s, file=sys.stderr)


if __name__ == "__main__":
    Bot().run()
